def _build_model(backend: str) -> NumpySpinModel | TorchSpinModel:
    spin = Spin(use_spin=[True, False, True], virtual_scale=[0.5, 0.0, 0.75])
    if backend == "numpy":
        return NumpySpinModel(_DummyNpBackbone(), spin)
    return TorchSpinModel(_DummyTorchBackbone(), spin)


def _to_backend(array: np.ndarray, backend: str) -> Any:
    if backend == "torch":
        dtype = torch.long if np.issubdtype(array.dtype, np.integer) else torch.float64
        return torch.tensor(array, dtype=dtype)
    return array.copy()


def _clone(value: Any, backend: str) -> Any:
    if backend == "torch":
        return value.clone()
    return value.copy()


def _max_abs_delta(lhs: Any, rhs: Any, backend: str) -> float:
    if backend == "torch":
        return float(torch.max(torch.abs(lhs - rhs)).item())
    return float(np.max(np.abs(lhs - rhs)))


def _set_vectors(array: Any, indices: list[int], values: list[list[float]], backend: str) -> None:
    for index, value in zip(indices, values, strict=True):
        if backend == "torch":
            array[0, index] = torch.tensor(value, dtype=array.dtype, device=array.device)
        else:
            array[0, index] = np.array(value, dtype=array.dtype)


